import{_ as p,a0 as i,w as l,s as g,ao as a,I as r,a1 as o,A as s,x as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"通過網絡方式安裝 Debian 7（Wheezy） | LCTT x X-CMD","titleTemplate":false,"description":"通過網絡方式安裝 Debian 7（Wheezy） | LCTT (201411) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"通過網絡方式安裝 Debian 7（Wheezy） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"通過網絡方式安裝 Debian 7（Wheezy） | LCTT (201411) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201411/20140919 Network Installation of Debian 7 (Whezzy) on Client Machines using DNSMASQ Network Boot Server","title":"通過網絡方式安裝 Debian 7（Wheezy）","tag":"201411","desc":""},"relativePath":"201411/20140919 Network Installation of Debian 7 (Whezzy) on Client Machines using DNSMASQ Network Boot Server.md","filePath":"[post].md"}'),m={name:"201411/20140919 Network Installation of Debian 7 (Whezzy) on Client Machines using DNSMASQ Network Boot Server.md"};function d(w,t,u,D,c,b){const e=i("Link");return l(),g("div",null,[t[19]||(t[19]=a('<h1 id="通過網絡方式安裝-debian-7-wheezy" tabindex="-1">通過網絡方式安裝 Debian 7（Wheezy） <a class="header-anchor" href="#通過網絡方式安裝-debian-7-wheezy" aria-label="Permalink to “通過網絡方式安裝 Debian 7（Wheezy）”">​</a></h1><p>本教程將指引你直接通過使用<strong>DNSMASQ</strong>作為<strong>PXE服務器（預啓動執行環境）</strong>，以網絡方式安裝<strong>Debian 7（Wheezy）</strong>，此種情況是假定你的服務器不提供任何CD/DVD/USB介質驅動器，或者它只能通過相連的監視器、鍵盤和鼠標操作。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Network-Debian-Instalaltion.png" alt="Debian 7 Network Installation on Client Machines"></p><p><em>客户機上的Debian 7網絡安裝</em></p><p><strong>DNSMASQ</strong>是一個輕量級網絡基礎架構服務器，它可以通過內建的DNS、DHCP和TFTP服務器提供如DNS、DHCP和網絡啓動等關鍵服務。</p><p>一旦PXE服務器啓動並運行，你可以指示你所有的客户機直接從網絡啓動，前提是你的客户機必須擁有一張支持網絡啓動的網卡，網絡啓動可以從BIOS的網絡啓動或啓動服務選項中啓用。</p><h3 id="前置閲讀" tabindex="-1">前置閲讀 <a class="header-anchor" href="#前置閲讀" aria-label="Permalink to “前置閲讀”">​</a></h3>',7)),r("ul",null,[r("li",null,[o(e,{href:"http://www.tecmint.com/debian-gnulinux-7-0-code-name-wheezy-server-installation-guide/"},{default:s(()=>[...t[0]||(t[0]=[n("Debian 7 (Wheezy)安裝指南",-1)])]),_:1})])]),t[20]||(t[20]=a(`<h3 id="步驟1-安裝及配置dnsmasq服務器" tabindex="-1">步驟1： 安裝及配置DNSMASQ服務器 <a class="header-anchor" href="#步驟1-安裝及配置dnsmasq服務器" aria-label="Permalink to “步驟1： 安裝及配置DNSMASQ服務器”">​</a></h3><p><strong>1.</strong> 首先，在安裝Debian服務器後，要確保你的系統使用的是<strong>靜態IP地址</strong>。因為除了網絡啓動之外，也要為你的整個網段提供DHCP服務。設置好靜態IP地址後，以root帳號或具有root權力的用户來運行以下命令，進行DNSMASQ服務器的安裝。</p><pre><code># apt-get install dnsmasq
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Install-Dnsmasq-in-Debian.png" alt="Install Dnsmasq Package"></p><p><em>安裝Dnsmasq包</em></p><p><strong>2.</strong> 安裝好DNSMASQ包後，你可以開始編輯配置文件。首先創建一個主配置文件的備份，然後使用下面的命令對<strong>dnsmasq.conf</strong>文件進行編輯。</p><pre><code># mv /etc/dnsmasq.conf  /etc/dnsmasq.conf.backup
# nano /etc/dnsmasq.conf
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Backup-dnsmasq-Configuration-file.png" alt="Backup Dnsmasq Configuration"></p><p><em>備份Dnsmasq配置</em></p><p><strong>3.</strong> 上面的備份過程適合重命名配置文件，所以新的文件應該是空，你可以使用以下描述的<strong>DNSMASQ</strong>配置文件節錄。</p><pre><code>interface=eth0
domain=debian.lan
dhcp-range=192.168.1.3,192.168.1.253,255.255.255.0,1h
dhcp-boot=pxelinux.0,pxeserver,192.168.1.100
pxe-prompt=&quot;Press F8 for menu.&quot;, 60
#pxe-service types: x86PC, PC98, IA64_EFI, Alpha, Arc_x86, Intel_Lean_Client, IA32_EFI, BC_EFI, Xscale_EFI and X86-64_EFI
pxe-service=x86PC, &quot;Install Debian 7 Linux from network server 192.168.1.100&quot;, pxelinux
enable-tftp
tftp-root=/srv/tftp
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Configure-dnsmasq.png" alt="Configuration of Dnsmasq"></p><p><em>Dnsmasq配置</em></p><ul><li><strong>interface</strong> – 服務器監聽的網絡接口。</li><li><strong>domain</strong> – 用你自己的域名替換。</li><li><strong>dhcp-range</strong> – 用你自己的網絡掩碼定義的網絡IP地址範圍。</li><li><strong>dhcp-boot</strong> – 保持默認，但使用你自己的服務器IP地址替換IP聲明。</li><li><strong>pxe-prompt</strong> – 保持默認 – 要求在<strong>敲擊F8鍵</strong> 進入菜單時等待60秒。</li><li><strong>pxe=service</strong> – 使用<strong>x86PC</strong>作為32位/64位架構，並進入引號字符串的菜單描述提示。其它值類型可能是：PC98，IA64_EFI，Alpha，Arc_x86，Intel_Lean_Client，IA32_EFI, BC_EFI，Xscale_EFI和 X86-64_EFI。</li><li><strong>enable-tftp</strong> – 啓用內建TFTP服務器。</li><li><strong>tftp-root</strong> – 使用/srv/tftp作為Debian網絡啓動文件的存放位置。</li></ul><h3 id="步驟2-下載debian網絡啓動文件並打開防火牆連接" tabindex="-1">步驟2: 下載Debian網絡啓動文件並打開防火牆連接 <a class="header-anchor" href="#步驟2-下載debian網絡啓動文件並打開防火牆連接" aria-label="Permalink to “步驟2: 下載Debian網絡啓動文件並打開防火牆連接”">​</a></h3><p><strong>4.</strong> 現在，該下載Debian網絡啓動文件了。首先，修改你當前工作目錄路徑到<strong>TFTP根目錄</strong>位置，此位置由最後的配置語句定義（<strong>/srv/tftp</strong>系統路徑）。</p>`,16)),r("p",null,[t[3]||(t[3]=n("轉到",-1)),o(e,{href:"http://www.debian.org/distrib/netinst#netboot"},{default:s(()=>[...t[1]||(t[1]=[n("Debian網絡安裝",-1)])]),_:1}),t[4]||(t[4]=n(" – ",-1)),o(e,{href:"http://ftp.nl.debian.org/debian/dists/wheezy/main/"},{default:s(()=>[...t[2]||(t[2]=[n("網絡啓動部分",-1)])]),_:1}),t[5]||(t[5]=n("的官方頁面鏡像，抓取以下文件，要抓取的文件取決於你想要安裝到客户端的系統架構。",-1))]),t[21]||(t[21]=a(`<p>下載好<strong>netboot.tar.gz</strong>文件後，同時提取歸檔（該過程描述只適用於64位，但對於其它系統架構也基本相同）。</p><pre><code># cd /srv/tftp/
# wget http://ftp.nl.debian.org/debian/dists/wheezy/main/installer-amd64/current/images/netboot/netboot.tar.gz
# tar xfz netboot.tar.gz
# wget http://ftp.nl.debian.org/debian/dists/wheezy/main/installer-amd64/current/images/SHA256SUMS
# wget http://ftp.nl.debian.org/debian/dists/wheezy/Release
# wget http://ftp.nl.debian.org/debian/dists/wheezy/Release.gpg
</code></pre><p>同時，必須確保<strong>TFTP</strong>目錄中的所有文件都可讓TFTP服務器讀取。</p><pre><code># chmod -R 755 /srv/tftp/
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Download-Debian-NetBoot-Files.png" alt="Download Debian NetBoot Files"></p><p><em>下載Debian網絡啓動文件</em></p><p>使用以下變量用於<strong>Debian網絡安裝</strong>鏡像和架構。</p><pre><code># wget http://&quot;$YOURMIRROR&quot;/debian/dists/wheezy/main/installer-&quot;$ARCH&quot;/current/images/netboot/netboot.tar.gz
# wget http://&quot;$YOURMIRROR&quot;/debian/dists/wheezy/main/installer-&quot;$ARCH&quot;/current/images/SHA256SUMS
# wget http://&quot;$YOURMIRROR&quot;/debian/dists/wheezy/Release
# wget http://&quot;$YOURMIRROR&quot;/debian/dists/wheezy/Release.gpg
</code></pre><p><strong>5.</strong> 下一步，啓動或重啓DNSMASQ守護進程，並運行netstat命令來獲取服務器監聽的端口列表。</p><pre><code># service dnsmasq restart
# netstat -tulpn | grep dnsmasq
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Start-Dnsmasq-Service.png" alt="Start Dnsmasq Service"></p><p><em>啓動Dnsmasq服務</em></p><p><strong>6.</strong> 基於Debian的發行版通常附帶了<strong>UFW防火牆</strong>包。使用以下命令來打開需要的<strong>DNSMASQ</strong>端口號：<strong>67</strong>（Bootps），<strong>69</strong>（TFTP），<strong>53</strong>（DNS）<strong>4011</strong>（代理DHCP）udp和<strong>53</strong> tcp（DNS）。</p><pre><code># ufw allow 69/udp
# ufw allow 4011/udp   ## Only if you have a ProxyDHCP on the network
# ufw allow 67/udp
# ufw allow 53/tcp
# ufw allow 53/udp
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Open-Dnsmasq-Ports-620x303.png" alt="Open Dnsmasq Ports"></p><p><em>開啓Dnsmasq端口</em></p><p>現在，位於你的客户機網絡接口上的PXE加載器將使用按以下順序從<strong>/srv/tftp/pxelinux.cfg</strong>目錄加載<strong>pxelinux</strong>配置文件。</p><ul><li>GUID文件</li><li>MAC文件</li><li>默認文件</li></ul><h3 id="步驟3-配置客户端從網絡啓動" tabindex="-1">步驟3： 配置客户端從網絡啓動 <a class="header-anchor" href="#步驟3-配置客户端從網絡啓動" aria-label="Permalink to “步驟3： 配置客户端從網絡啓動”">​</a></h3><p><strong>7.</strong> 要為你的客户端計算機啓用網絡啓動，請進入系統<strong>BIOS配置</strong>（如何進入BIOS設置，請查閲硬件主板提供商的文檔）。</p><p>轉到<strong>啓動菜單</strong>，然後選擇<strong>網絡啓動</strong>作為<strong>首要啓動設備</strong>（在某些系統上，你可以不用進入BIOS配置就能選擇啓動設備，只要在<strong>BIOS自檢</strong>時按一個鍵就可以進行選擇了）。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Select-BIOS-Settings.png" alt="Select BIOS Settings"></p><p><em>選擇BIOS設置</em></p><p><strong>8。</strong> 在編輯啓動順序後，通常按<strong>F10</strong>來保存BIOS設置。重啓後，你的客户端計算機應該可以直接從網絡啓動了，應該會出第一個<strong>PXE</strong>提示，要求你按<strong>F8</strong>鍵進入菜單。</p><p>接下來，敲擊<strong>F8</strong>鍵來進入，會出現一個新的提示。敲擊<strong>回車</strong>鍵，屏幕上會出現<strong>Debian安裝器</strong>主界面提示，如下圖所示。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Boot-Menu-Selection.png" alt="Boot Menu Selection"></p><p><em>啓動菜單選擇</em></p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Select-Debian-Installer-Boot.png" alt="Select Debian Installer Boot"></p><p><em>選擇Debian安裝器啓動</em></p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Select-Debian-Install.png" alt="Select Debian Install"></p><p><em>選擇Debian安裝</em></p><p>從這裏開始，你可以使用Debian 7 Wheezy安裝進程將Debian安裝到你的機器上了（安裝鏈接見上面）。然而，為了能夠完成安裝進程，你也需要確保你的機器上互聯網連接已經激活。</p><h3 id="步驟4-dnsmasq服務器排障並在系統範圍內啓用" tabindex="-1">步驟4： DNSMASQ服務器排障並在系統範圍內啓用 <a class="header-anchor" href="#步驟4-dnsmasq服務器排障並在系統範圍內啓用" aria-label="Permalink to “步驟4： DNSMASQ服務器排障並在系統範圍內啓用”">​</a></h3><p><strong>9.</strong> 要診斷服務器以查詢最終是否發生問題或要查詢其它提供給客户端的信息，運行以下命令來打開日誌文件。</p><pre><code># tailf /var/log/daemon.log
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Debbug-DNSMASQ-Server.png" alt="Debug DNSMASQ Server"></p><p><em>DNSMASQ服務器排障</em></p><p><strong>10.</strong> 如果服務器測試中已一切就緒，你現在可以在<strong>sysv-rc-conf</strong>包的幫助下，啓用<strong>DNSMASQ</strong>守護進程自啓動，以使該進程在系統重啓後自動啓動。</p><pre><code># apt-get install sysv-rc-conf
# sysv-rc-conf dnsmaq on
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Enable-DNSMASQ-Daemon.png" alt="Enable DNSMASQ Daemon"></p><p><em>啓用DNSMASQ守護進程</em></p><p>到此為止吧！現在你的<strong>PXE</strong>服務器已經整裝待發，隨時準備好分配IP地址了（<strong>DHCP</strong>），併為你所有網段中的客户端提供需要的啓動信息，這些信息配置用來從網絡啓動並安裝Debian Wheezy。</p><p>使用PXE網絡啓動安裝在服務器主機數量很多時很有優勢，因為你可以在短時間內火同時設置整個網絡基礎架構，為版本升級提供了方便，也可以通過kickstart文件使整個安裝的全自動化。</p><hr>`,44)),r("p",null,[t[7]||(t[7]=n("via: ",-1)),o(e,{href:"http://www.tecmint.com/network-installation-of-debian-7-on-client-machines/"},{default:s(()=>[...t[6]||(t[6]=[n("http://www.tecmint.com/network-installation-of-debian-7-on-client-machines/",-1)])]),_:1})]),r("p",null,[t[11]||(t[11]=n("作者：",-1)),o(e,{href:"http://www.tecmint.com/author/cezarmatei/"},{default:s(()=>[...t[8]||(t[8]=[n("Matei Cezar",-1)])]),_:1}),t[12]||(t[12]=n(" 譯者：",-1)),o(e,{href:"https://github.com/GOLinux"},{default:s(()=>[...t[9]||(t[9]=[n("GOLinux",-1)])]),_:1}),t[13]||(t[13]=n(" 校對：",-1)),o(e,{href:"https://github.com/wxy"},{default:s(()=>[...t[10]||(t[10]=[n("wxy",-1)])]),_:1})]),r("p",null,[t[16]||(t[16]=n("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[14]||(t[14]=[n("LCTT",-1)])]),_:1}),t[17]||(t[17]=n(" 原創翻譯，",-1)),o(e,{href:"http://linux.cn/"},{default:s(()=>[...t[15]||(t[15]=[n("Linux中國",-1)])]),_:1}),t[18]||(t[18]=n(" 榮譽推出",-1))])])}const I=p(m,[["render",d]]);export{f as __pageData,I as default};
